console.log(JSON.stringify(log));
return $input.all();

const input = $json || {};
const source_table = String(input.source_table || '').trim();
if (!source_table) throw new Error('source_table é obrigatório');
const limit = Math.max(1, Math.min(500, +(input.limit) || 50));
const filters = input.filters && Object.keys(input.filters).length > 0 ? input.filters : null;
return [{ json: { source_table, limit, filters } }];

const params = $('Prepare params').first().json;
const rows = $input.all();
const firstErr = rows[0] && rows[0].json && rows[0].json.error;
if (firstErr) {
  return [{ json: { ok: false, data: null, error: String(firstErr.message || firstErr) } }];
}
const data = rows
  .map(r => r.json && r.json.record ? r.json.record : null)
  .filter(Boolean);
return [{ json: { ok: true, source_table: params.source_table, count: data.length, data, error: null } }];
